import marshmallow as mm
import pytest

def test_file_url_without_host():
    class LOL(mm.Schema):
        url = mm.fields.Url(schemes={'file'})

    res = LOL().load(dict(url="file:///var/storage/somefile.zip"))
    assert res == {"url": "file:///var/storage/somefile.zip"}

